WITH lines AS (SELECT id, service, latency_ms, status_code, key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, attr_value), metrics AS (SELECT id, service, CORR(status_code, latency_ms) OVER (PARTITION BY service) AS corr_status_code_latency_ms FROM lines), scored AS (SELECT *, AVG(corr_status_code_latency_ms) OVER w_ordered AS service_avg_corr_status_code_latency_ms, MIN(corr_status_code_latency_ms) OVER w_ordered AS service_min_corr_status_code_latency_ms, RANK() OVER (ORDER BY corr_status_code_latency_ms DESC NULLS LAST) AS corr_status_code_latency_ms_rank, RANK() OVER w_running AS corr_status_code_latency_ms_rank_2 FROM metrics WINDOW w_ordered AS (PARTITION BY service), w_running AS (PARTITION BY service ORDER BY corr_status_code_latency_ms NULLS LAST)), enriched AS (SELECT id, service, corr_status_code_latency_ms, service_avg_corr_status_code_latency_ms, service_min_corr_status_code_latency_ms, ROUND(corr_status_code_latency_ms_rank_2 / SUM(corr_status_code_latency_ms_rank_2) OVER (PARTITION BY service), 4) AS corr_status_code_latency_ms_rank_2_share, RANK() OVER (PARTITION BY service ORDER BY corr_status_code_latency_ms DESC NULLS LAST) AS corr_status_code_latency_ms_rank_3, CUME_DIST() OVER (PARTITION BY service ORDER BY service_avg_corr_status_code_latency_ms NULLS FIRST) AS service_avg_corr_status_code_latency_ms_cume_dist FROM scored), summary AS (SELECT service, CASE WHEN service_min_corr_status_code_latency_ms >= 1 THEN 'HIGH' ELSE 'LOW' END AS service_min_corr_status_code_latency_ms_tier, MAX(corr_status_code_latency_ms_rank_3) FILTER (WHERE service = 'auth') AS auth_max_corr_status_code_latency_ms_rank_3, ROUND(AVG(service_avg_corr_status_code_latency_ms), 2) AS avg_service_avg_corr_status_code_latency_ms, MAX(service_avg_corr_status_code_latency_ms) FILTER (WHERE service = 'billing') AS billing_max_service_avg_corr_status_code_latency_ms FROM enriched GROUP BY GROUPING SETS ((service, CASE WHEN service_min_corr_status_code_latency_ms >= 1 THEN 'HIGH' ELSE 'LOW' END), (service), ())) SELECT service, service_min_corr_status_code_latency_ms_tier, auth_max_corr_status_code_latency_ms_rank_3, avg_service_avg_corr_status_code_latency_ms, billing_max_service_avg_corr_status_code_latency_ms, CASE WHEN service RLIKE '^(checkout|billing)$' THEN 'GROUP_A' WHEN service RLIKE '^(auth|search)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS service_zone FROM summary ORDER BY auth_max_corr_status_code_latency_ms_rank_3 DESC NULLS FIRST
